package com.mantou.salesdialer.contacts;
import android.app.Activity;import android.os.Bundle;import android.widget.TextView;import android.util.AtomicFile;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;
import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.json.JSONObject;
import com.mantou.salesdialer.contacts.ContactTaskModel.*;import com.mantou.salesdialer.contacts.SyntheticWorkspaceSession.*;
/** Fixed isolated workspace checks only; never opens the user workspace, DEMO or real catalog. */
public final class SyntheticWorkspaceCheckActivity extends Activity {
 private int checks;private void check(boolean ok){checks++;if(!ok)throw new IllegalStateException("WORKSPACE_ASSERTION_"+checks);}private void denied(Runnable run,String reason){checks++;try{run.run();}catch(RuntimeException e){if(reason.equals(e.getMessage()))return;throw new IllegalStateException("UNEXPECTED:"+e.getMessage(),e);}throw new IllegalStateException("EXPECTED_"+reason);}
 private String name(){return "workspace-fixture-"+UUID.randomUUID().toString().replace("-","")+".db";}private ContactTaskStore open(String n){return ContactTaskStore.workspaceFixture(this,n,p->{});}
 private static final long NOW=Instant.parse("2026-10-19T01:00:00Z").toEpochMilli();private SyntheticTaskLoop.Time time(){return new SyntheticTaskLoop.Time(){public Clock wall(){return Clock.fixed(Instant.ofEpochMilli(NOW),ZoneOffset.UTC);}public long elapsedMillis(){return 1000;}public String bootId(){return "SYNTHETIC-WORKSPACE-FIXTURE";}};}
 private void runChecks()throws Exception{
  String normal=name();try(ContactTaskStore s=open(normal)){var imported=s.importWorkspaceIds("SIM-001\nSIM-001\n\nSIM-002");check(imported.added==2&&imported.duplicates==1&&imported.blanks==1);Contact c=s.list().stream().filter(x->SyntheticWorkspaceModel.label(x.targetKey).equals("SIM-001")).findFirst().orElseThrow();s.qualify(c.id,1,Qualification.UNKNOWN,SyntheticWorkspaceModel.CHANGE_SOURCE);s.refuse(c.id,2);var repeated=s.importWorkspaceIds("SIM-001\nSIM-002");check(repeated.added==0&&repeated.duplicates==2&&s.get(c.id).contact.refused&&s.get(c.id).contact.revision==3&&s.get(c.id).task.contactRevision==1);denied(()->s.importWorkspaceIds("SIM-003\n12345678901"),"INVALID_LINE_2");check(s.list().size()==2);denied(()->s.importContact(new Input(Origin.CONTACT_INTAKE,"a".repeat(64),Qualification.CONFIRMED,SyntheticWorkspaceModel.INPUT_SOURCE)),"FOREIGN_WORKSPACE_TARGET");}
  try(ContactTaskStore s=open(normal)){check(s.list().size()==2&&s.list().stream().anyMatch(c->c.refused));}
  String failure=name();AtomicInteger count=new AtomicInteger();try(ContactTaskStore s=ContactTaskStore.workspaceFixture(this,failure,p->{if(p.equals("AFTER_CONTACT_INSERT")&&count.incrementAndGet()==2)throw new IllegalStateException("BATCH_WRITE_FAILED");})){denied(()->s.importWorkspaceIds("SIM-011\nSIM-012\nSIM-013"),"BATCH_WRITE_FAILED");}try(ContactTaskStore s=open(failure)){check(Arrays.equals(s.fixtureCounts(),new long[]{0,0,0}));}
  String wrong=name();try(ContactTaskStore s=open(wrong)){s.importWorkspaceIds("SIM-021");}try(SQLiteDatabase db=SQLiteDatabase.openDatabase(getDatabasePath(wrong).getAbsolutePath(),null,SQLiteDatabase.OPEN_READWRITE)){db.execSQL("UPDATE catalog_meta SET kind='CONTACT_TASK_CATALOG'");}denied(()->{try(ContactTaskStore ignored=open(wrong)){}},"CONTACT_STORE_TYPE_MISMATCH");try(SQLiteDatabase db=SQLiteDatabase.openDatabase(getDatabasePath(wrong).getAbsolutePath(),null,SQLiteDatabase.OPEN_READWRITE);Cursor c=db.rawQuery("SELECT COUNT(*) FROM contacts",null)){c.moveToFirst();check(c.getLong(0)==1);}
  String session=name();try(SyntheticWorkspaceSession s=new SyntheticWorkspaceSession(open(session),time())){s.importIds("SIM-031\nSIM-032");View view=s.view();Row first=view.contacts.get(0),second=view.contacts.get(1);s.immediate(first,view.plan.version);View pending=s.view();check(pending.counters.pending==1&&pending.counters.apiReceipts==1);denied(()->s.immediate(second,pending.plan.version),"OCCUPIED");s.result(pending.pending(),"UNKNOWN");denied(()->s.closeUnknown(s.view().pending(),false),"NO_PENDING_CONFIRMATION_REQUIRED");s.closeUnknown(s.view().pending(),true);View closed=s.view();check(closed.counters.pending==0&&closed.counters.closedUnknown==1&&closed.counters.manualKnown==0);s.immediate(second,closed.plan.version);s.result(s.view().pending(),"NO_ANSWER");check(s.view().counters.attempts==2&&s.view().counters.manualKnown==1);View latest=s.view();Row stale=latest.contacts.get(0);s.qualify(stale,Qualification.UNKNOWN);View changed=s.view();denied(()->s.immediate(changed.contacts.get(0),changed.plan.version),"STALE_CONTACT");s.qualify(changed.contacts.get(0),Qualification.CONFIRMED);s.refresh(s.view().contacts.get(0));View refreshed=s.view();check(refreshed.contacts.get(0).eligible());s.arrange(refreshed.contacts.get(0),refreshed.plan.version,"2026-10-19 09:05");check(!s.view().plan.paused);}
  try(SyntheticWorkspaceSession s=new SyntheticWorkspaceSession(open(session),time())){check(s.view().plan.paused&&s.view().counters.attempts==2);check(s.view().attempts.stream().anyMatch(a->a.unknownClosed&&a.manualResult.equals("UNKNOWN")&&a.connectedConfirmed==null));}
  // Reproduce real moving-clock reads: due must be anchored inside the plan transaction.
  java.util.concurrent.atomic.AtomicLong ticks=new java.util.concurrent.atomic.AtomicLong(NOW);
  Clock advancing=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public long millis(){return ticks.getAndIncrement();}public Instant instant(){return Instant.ofEpochMilli(millis());}};
  SyntheticTaskLoop.Time moving=new SyntheticTaskLoop.Time(){public Clock wall(){return advancing;}public long elapsedMillis(){return 1000;}public String bootId(){return "SYNTHETIC-MOVING-CLOCK";}};
  try(SyntheticWorkspaceSession s=new SyntheticWorkspaceSession(open(name()),moving)){s.importIds("SIM-041");s.immediate(s.view().contacts.get(0),s.view().plan.version);check(s.view().counters.attempts==1&&s.view().counters.apiReceipts==1);}
 }
 @Override public void onCreate(Bundle saved){super.onCreate(saved);TextView view=new TextView(this);view.setText("正在检查独立合成工作区……\n不操作用户工作区或电话。");setContentView(view);new Thread(()->{JSONObject result=new JSONObject();boolean ok=false;try{runChecks();result.put("decision","PASSED");ok=true;}catch(Exception e){try{result.put("decision","FAILED").put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){}}try{result.put("source","ISOLATED_SYNTHETIC_WORKSPACE_FIXTURE").put("tests","T631-T635").put("assertions",checks).put("actualPhoneCalls",0).put("userWorkspaceOpened",false).put("productionAuthenticated",false);AtomicFile file=new AtomicFile(new File(getFilesDir(),"synthetic-workspace-check.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(result.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}catch(Exception ignored){ok=false;}final boolean passed=ok;runOnUiThread(()->view.setText(passed?"独立合成工作区规则检查通过":"规则检查未通过，保留数据和报告。"));},"workspace-fixture").start();}
}
